class Map2 {
	constructor() {
		this.version = 0;
		this.mapname = "";
		this.author = "";
		this.platformArray = [];
		this.spawnArray = [];
		this.platformNames = [];
		this.spawnNames = [];
		this.capZoneArray = [];
		this.capZoneNames = [];
		this.gravity = 20;
		this.ppm = 12;
		this.discFriction = 0;
		this.discRestitution = .8;
		this.discDensity = 1;
		this.discLinearDamping = 0;
		this.discRadius = 1;
		this.discAllForce = 12;
		this.respawn = false;
		this.noCollide = false
	}
	writeExternal() {}
	readExternal(f270a0) {
		this.version = f270a0.readShort();
		this.mapname = f270a0.readUTF();
		if (this.mapname.length > 25) {
			this.mapname = this.mapname.slice(0, 25)
		}
		this.author = f270a0.readUTF();
		if (this.author.length > 25) {
			this.author = this.author.slice(0, 35)
		}
		this.gravity = f270a0.readDouble();
		this.ppm = f270a0.readDouble();
		this.ppm = Math.max(5, this.ppm);
		this.ppm = Math.min(30, this.ppm);
		this.discFriction = f270a0.readDouble();
		this.discRestitution = f270a0.readDouble();
		this.discDensity = f270a0.readDouble();
		this.discLinearDamping = f270a0.readDouble();
		this.discRadius = f270a0.readDouble();
		this.discAllForce = f270a0.readDouble();
		const f270v0 = f270a0.readShort();
		this.platformArray = [];
		this.platformNames = [];
		for (let i = 0; i < f270v0; i++) {
			this.platformArray.push(f270a0.readObject());
			this.platformNames.push(f270a0.readUTF())
		}
		const f270v2 = f270a0.readShort();
		this.spawnArray = [];
		this.spawnNames = [];
		for (let i = 0; i < f270v2; i++) {
			this.spawnArray.push(f270a0.readObject());
			this.spawnNames.push(f270a0.readUTF())
		}
		if (this.version >= 2) {
			this.capZoneArray = f270a0.readObject()
		} else {
			this.capZoneArray = []
		}
		if (this.version >= 3) {
			this.capZoneNames = f270a0.readObject()
		} else {
			this.capZoneNames = []
		}
		if (this.version == 4) {
			const f270v4 = f270a0.readBoolean();
			this.noCollide = f270v4;
			this.respawn = f270v4
		} else if (this.version > 4) {
			this.noCollide = f270a0.readBoolean();
			this.respawn = f270a0.readBoolean()
		}
	}
}
