class BonkObject {
	constructor() {
		this.version = 0;
		this.x = 0;
		this.y = 0;
		this.shapeArray = [];
		this.restitution = .8;
		this.friction = 0;
		this.density = 1;
		this.angle = 0;
		this.angularVelocity = 0;
		this.isDynamic = false;
		this.xv = 0;
		this.yv = 0;
		this.linearDamping = 0;
		this.angularDamping = 0;
		this.rotates = false;
		this.rotatePivotX = 0;
		this.rotatePivotY = 0;
		this.stiffness = 0;
		this.springy = false;
		this.springyUpper = 100;
		this.springyLower = -100;
		this.springyAnchorX = 0;
		this.springyAnchorY = 0;
		this.springyForce = 1e6;
		this.path = false;
		this.pathAngle = Math.PI / 2;
		this.pathUpper = 100;
		this.pathLower = -100;
		this.pathAnchorX = 0;
		this.pathAnchorY = 0;
		this.pathMaxSpeed = 50;
		this.pathForce = 1e6
	}
	writeExternal() {}
	readExternal(f274a0) {
		this.version = f274a0.readShort();
		if (this.version <= 3) {
			this.x = f274a0.readDouble();
			this.y = f274a0.readDouble();
			this.shapeArray = [new Shape];
			this.shapeArray[0].localX = 0;
			this.shapeArray[0].localY = 0;
			this.shapeArray[0].localAngle = 0;
			this.shapeArray[0].width = f274a0.readDouble();
			this.shapeArray[0].height = f274a0.readDouble();
			this.restitution = f274a0.readDouble();
			this.density = f274a0.readDouble();
			this.friction = f274a0.readDouble();
			this.angle = f274a0.readDouble();
			this.angularVelocity = f274a0.readDouble();
			this.shapeArray[0].shapeID = f274a0.readShort();
			this.isDynamic = f274a0.readBoolean();
			if (this.isDynamic) {
				this.xv = f274a0.readDouble();
				this.yv = f274a0.readDouble();
				this.linearDamping = f274a0.readDouble();
				this.angularDamping = f274a0.readDouble();
				this.rotates = f274a0.readBoolean();
				if (this.rotates) {
					this.rotatePivotX = f274a0.readDouble();
					this.rotatePivotY = f274a0.readDouble();
					this.stiffness = f274a0.readDouble()
				}
			}
			if (this.version >= 2) {
				this.shapeArray[0].color = f274a0.readUint()
			} else {
				if (this.isDynamic) {
					this.shapeArray[0].color = 9159498
				} else {
					this.shapeArray[0].color = 5812595
				}
			}
			if (this.version >= 3) {
				f274a0.readShort();
				this.shapeArray[0].death = f274a0.readBoolean()
			} else {
				this.shapeArray[0].death = false
			}
		}
		if (this.version >= 4) {
			this.x = f274a0.readDouble();
			this.y = f274a0.readDouble();
			const f274v1 = f274a0.readShort();
			this.shapeArray = [];
			for (let i = 0; i < f274v1; i++) {
				this.shapeArray[i] = new Shape;
				this.shapeArray[i].localX = f274a0.readDouble();
				this.shapeArray[i].localY = f274a0.readDouble();
				this.shapeArray[i].width = f274a0.readDouble();
				this.shapeArray[i].height = f274a0.readDouble();
				this.shapeArray[i].localAngle = f274a0.readDouble();
				this.shapeArray[i].shapeID = f274a0.readShort();
				this.shapeArray[i].color = f274a0.readUint();
				this.shapeArray[i].death = f274a0.readBoolean();
				if (this.version >= 7) {
					this.shapeArray[i].noPhysics = f274a0.readBoolean()
				}
				if (this.version == 4 && this.shapeArray[i].shapeID == 5) {
					this.shapeArray[i].height = Math.round(.866 * this.shapeArray[i].width)
				}
			}
			this.restitution = f274a0.readDouble();
			this.density = f274a0.readDouble();
			this.friction = f274a0.readDouble();
			this.angle = f274a0.readDouble();
			this.angularVelocity = f274a0.readDouble();
			this.isDynamic = f274a0.readBoolean();
			if (this.isDynamic) {
				this.xv = f274a0.readDouble();
				this.yv = f274a0.readDouble();
				this.linearDamping = f274a0.readDouble();
				this.angularDamping = f274a0.readDouble();
				this.rotates = f274a0.readBoolean();
				if (this.rotates) {
					this.rotatePivotX = f274a0.readDouble();
					this.rotatePivotY = f274a0.readDouble();
					this.stiffness = f274a0.readDouble()
				}
				if (this.version >= 6) {
					this.springy = f274a0.readBoolean();
					if (this.springy) {
						this.springyUpper = f274a0.readDouble();
						this.springyLower = -this.springyUpper;
						this.springyForce = f274a0.readDouble();
						this.springyAnchorX = f274a0.readDouble();
						this.springyAnchorY = f274a0.readDouble()
					}
					this.path = f274a0.readBoolean();
					if (this.path) {
						this.pathAngle = f274a0.readDouble();
						this.pathUpper = f274a0.readDouble();
						this.pathLower = -this.pathUpper;
						this.pathMaxSpeed = f274a0.readDouble();
						this.pathForce = f274a0.readDouble();
						this.pathAnchorX = f274a0.readDouble();
						this.pathAnchorY = f274a0.readDouble()
					}
				}
			}
		}
	}
}
