class CaptureZone {
	constructor() {
		this.version = 0;
		this.radius = 0;
		this.x = 0;
		this.y = 0;
		this.captureLimit = 0;
		this.ownerID = 0;
		this.framesToDetonate = 0
	}
	writeExternal() {}
	readExternal(f281a0) {
		for (let i = 0; i < 8; i++) {
			const f281v1 = f281a0.readByte();
			if (f281v1 == BonkView.T_INT) {
				this[f281a0.bodgeCaptureZoneDataIdentifierArray[i]] = f281a0.readInt29()
			} else if (f281v1 == BonkView.T_DOUBLE) {
				this[f281a0.bodgeCaptureZoneDataIdentifierArray[i]] = f281a0.readDouble()
			}
		}
	}
	readAnonymous(f282a0) {
		f282a0.bodgeCaptureZoneDataIdentifierArray = [];
		for (let i = 0; i < 8; i++) {
			const f282v1 = f282a0.readByte();
			const f282v2 = (f282v1 - 1) / 2;
			const f282v3 = new Uint8Array(f282v2);
			for (let j = 0; j < f282v2; j++) {
				f282v3[j] = f282a0.readByte()
			}
			const f282v5 = BonkView.textDec.decode(f282v3);
			f282a0.bodgeCaptureZoneDataIdentifierArray.push(f282v5)
		}
		this.readExternal(f282a0)
	}
}
