			f671v2.textContent = f563v161[f563v103[f670v1[f671a0][1]]];
			f671v2.classList.add("redefineControls_selectionCell");
			const f671v3 = f671v0.insertCell(2);
			f671v3.style.width = "27%";
			f671v3.textContent = f563v161[f563v103[f670v1[f671a0][2]]];
			f671v3.classList.add("redefineControls_selectionCell");
			const f671v4 = f671v0.insertCell(3);
