class FPS {
	constructor(element, seconds) {
		this.updateSeconds = seconds;
		this.currentCount = 0;
		setInterval(() => {
			this.update()
		}, seconds * 1e3);
		this.div = document.createElement("div");
		this.div.style.position = "absolute";
		this.div.style.width = "50px";
		this.div.style.height = "20px";
		this.div.style.color = "#bbbbbb";
		this.div.style.top = "36px";
		this.div.style.left = "5px";
		this.div.style.fontFamily = "futurept_b1";
		this.div.style.display = "none";
		this.showing = false;
		element.appendChild(this.div)
	}
	frameDone() {
		if (!this.showing) {
			return
		}
		this.currentCount++
	}
	update() {
		if (!this.showing) {
			return
		}
		const fps = this.currentCount * (1 / this.updateSeconds);
		this.currentCount = 0;
		this.div.textContent = fps + "FPS"
	}
	show() {
		this.showing = true;
		this.div.style.display = "block"
	}
	hide() {
		this.showing = false;
		this.div.style.display = "none"
	}
}
