function SoundHandler() {
	const sounds = {};
	const pendingSounds = [];
	const capIncreaseSound = new Howl({
		src: [GameResources.soundStrings.capIncrease],
		volume: .5,
		loop: false
	});
	const capDecreaseSound = new Howl({
		src: [GameResources.soundStrings.capDecrease],
		volume: .5,
		loop: false
	});
	this.playSound = function(type, stereoPosition, volume, step) {
		if (game.mute) {
			return
		}
		if (game.preClickMute) {
			return
		}
		if (!sounds[type]) {
			sounds[type] = {
				howls: [],
				sumVolThisStep: 0
			}
		}
		if (sounds[type].howls.length >= 10) {
			return
		}
		if (sounds[type].sumVolThisStep >= 15) {
			return
		}
		if (step != undefined) {
			for (let i = 0; i < pendingSounds.length; i++) {
				if (pendingSounds[i].f == step && pendingSounds[i].i == type) {
					return
				}
			}
		}
		if (type == "capDecrease") {
			capDecreaseSound.volume(volume);
			capDecreaseSound.stereo(stereoPosition);
			if (!game.mute) {
				capDecreaseSound.play()
			}
			return
		} else if (type == "capIncrease") {
			capIncreaseSound.volume(volume);
			capIncreaseSound.stereo(stereoPosition);
			if (!game.mute) {
				capIncreaseSound.play()
			}
			return
		}
		const soundURI = GameResources.soundStrings[type];
		const sound = new Howl({
			src: [soundURI],
			volume: volume
		});
		sound.stereo(stereoPosition);
		sound.play();
		sounds[type].howls.push(sound);
		sounds[type].sumVolThisStep += volume;
		pendingSounds.push({
			i: type,
			f: step
		});
		if (pendingSounds.length > 5) {
			pendingSounds.shift()
		}
		sound.on("end", function() {
			const soundIndex = sounds[type].howls.indexOf(this);
			if (soundIndex != -1) {
				sounds[type].howls.splice(soundIndex, 1)
			}
		})
	};
	this.resetSumVols = function() {
		for (let i in sounds) {
			if (Object.prototype.hasOwnProperty.call(sounds, i)) {
				sounds[i].sumVolThisStep = 0
			}
		}
	}
}
